    // The first 3 components are the spatial velocity, 4th component relates to expansion
    double a = plane.a(0);
    double b = plane.a(1);
    double c = plane.a(2);
    double d = plane.a(3);

    // Normalize by the 4th component to get 3D velocity
    if (std::abs(d) < 1e-12) {
        return Vector(0, 0, 0);
    }

    double scale = -0.5 / d;
    return Vector(a * scale, b * scale, c * scale);

